service.method:

	SELECT COUNT(SIAD.SMR_NUMBER) AS COUNT
		 , SIAD.RE_FLAG
		 , SIAD.CONFIRM_DATE
	FROM  SSIAD SIAD
	WHERE SIAD.HOUSE_CODE = ${session.HOUSE_CODE}
	AND   SIAD.COMPANY_CODE = ${session.COMPANY_CODE}
    AND   SIAD.DEL_FLAG != 'Y'
	AND   SIAD.SMR_STATUS = 'C'
  	AND   SIAD.CONFIRM_DATE >= $S{F_CALENDAR_FROM}
	AND   SIAD.CONFIRM_DATE <= $S{F_CALENDAR_TO}
	GROUP BY SIAD.RE_FLAG
		   , SIAD.CONFIRM_DATE
